const policy = {
  en:{language:'Choose language',get:'Download Rattil',eyebrow:'Your privacy matters',title:'Privacy policy',updated:'Last updated: 28 October 2026',back:'← Back to Rattil',tagline:'A free Quran learning project.',sections:[
    ['Who this covers','This policy describes the Rattil Android app and this Rattil download website, maintained as a non-commercial project. The app is provided without an account, advertisements, analytics, or in-app tracking.'],
    ['Information on your device','The app saves settings, bookmarks, reading position, and learning progress locally on your device. It uses your microphone only when you start recitation practice. Speech recognition runs on the device; the app does not send microphone recordings or recognition results to a Rattil server. You can manage or remove the app’s local data through Android settings.'],
    ['Network requests','The app can access the internet to download Quran recitation audio you choose. Those requests go to the audio host, which may receive ordinary connection information such as your IP address. Audio you have downloaded is stored on your device for offline playback. The website’s APK and source links open GitHub; GitHub processes those requests under its own privacy policy. Rattil does not control the independent services’ data practices.'],
    ['This website','The site does not use analytics, advertising, cookies, or tracking scripts. Your selected language is saved in your browser’s local storage so it can be remembered on a later visit. The site’s hosting provider may process standard web request data to deliver and protect the site.'],
    ['Children and accounts','Rattil does not ask for a name, email address, account, or payment information. No personal information is intentionally collected by Rattil.'],
    ['Changes and contact','This policy may be updated when the app or website changes. The current version will be published on this page. For questions or concerns, contact the maintainers through the project’s public GitHub repository: <a href="https://github.com/zarsalene/Quran_AI_app/issues">Rattil on GitHub</a>.']
  ]},
  fr:{language:'Choisir la langue',get:'Télécharger Rattil',eyebrow:'Votre vie privée compte',title:'Politique de confidentialité',updated:'Mise à jour : 28 octobre 2026',back:'← Retour à Rattil',tagline:'Un projet gratuit pour apprendre le Coran.',sections:[
    ['Champ d’application','Cette politique concerne l’application Android Rattil et ce site de téléchargement, maintenus dans le cadre d’un projet non commercial. L’application ne nécessite aucun compte et ne comporte ni publicité, ni outil d’analyse, ni suivi intégré.'],
    ['Informations conservées sur votre appareil','L’application enregistre localement vos réglages, signets, position de lecture et progression. Elle utilise le microphone uniquement lorsque vous commencez un exercice de récitation. La reconnaissance vocale s’effectue sur l’appareil ; les enregistrements et résultats ne sont pas envoyés à un serveur Rattil. Vous pouvez gérer ou supprimer les données locales dans les paramètres Android.'],
    ['Connexions réseau','L’application peut accéder à Internet pour télécharger les récitations que vous choisissez. Le service audio peut recevoir des informations ordinaires de connexion, comme votre adresse IP. Les fichiers audio téléchargés sont conservés sur l’appareil pour une écoute hors ligne. Les liens de téléchargement et de code source ouvrent GitHub, qui traite ces requêtes selon sa propre politique. Rattil ne contrôle pas les pratiques des services indépendants.'],
    ['Ce site','Le site n’utilise ni outil d’analyse, ni publicité, ni cookie, ni script de suivi. La langue choisie est enregistrée dans le stockage local du navigateur afin d’être mémorisée lors d’une prochaine visite. L’hébergeur peut traiter les données habituelles des requêtes web pour fournir et protéger le site.'],
    ['Enfants et comptes','Rattil ne demande ni nom, ni adresse e-mail, ni compte, ni paiement. Rattil ne collecte intentionnellement aucune information personnelle.'],
    ['Modifications et contact','Cette politique pourra être actualisée si l’application ou le site évolue. La version à jour sera publiée sur cette page. Pour toute question, contactez les mainteneurs via le dépôt GitHub public : <a href="https://github.com/zarsalene/Quran_AI_app/issues">Rattil sur GitHub</a>.']
  ]},
  ar:{language:'اختر اللغة',get:'نزّل رتّل',eyebrow:'خصوصيتك تهمّنا',title:'سياسة الخصوصية',updated:'آخر تحديث: 28 أكتوبر 2026',back:'العودة إلى رتّل ←',tagline:'مشروع مجاني لتعلّم القرآن.',sections:[
    ['نطاق السياسة','توضح هذه السياسة طريقة تعامل تطبيق رتّل لنظام أندرويد وموقع تنزيل رتّل مع المعلومات. يُدار المشروع على أساس غير تجاري. لا يتطلب التطبيق حسابًا، ولا يحتوي على إعلانات أو تحليلات أو أدوات تتبّع.'],
    ['المعلومات على جهازك','يحفظ التطبيق الإعدادات والعلامات وموضع القراءة والتقدّم التعليمي محليًا على جهازك. ولا يستخدم الميكروفون إلا عند بدء تدريب التلاوة. يعمل التعرّف الصوتي على الجهاز؛ ولا يرسل التطبيق التسجيلات أو نتائج التعرّف إلى خادم رتّل. يمكنك إدارة بيانات التطبيق المحلية أو حذفها من إعدادات أندرويد.'],
    ['اتصالات الشبكة','قد يتصل التطبيق بالإنترنت لتنزيل التلاوات التي تختارها. وقد يستقبل مزوّد الصوت معلومات الاتصال المعتادة مثل عنوان IP. تُحفظ التلاوات المنزّلة على جهازك للاستماع دون اتصال. تفتح روابط ملف التطبيق والمصدر موقع GitHub الذي يعالج الطلبات وفق سياسة الخصوصية الخاصة به. لا يتحكم رتّل بممارسات الخدمات المستقلة.'],
    ['هذا الموقع','لا يستخدم الموقع تحليلات أو إعلانات أو ملفات تعريف ارتباط أو نصوصًا للتتبّع. تُحفظ اللغة التي تختارها في التخزين المحلي للمتصفح لتذكّرها في زيارتك المقبلة. وقد يعالج مزوّد استضافة الموقع بيانات طلبات الويب المعتادة لتقديم الخدمة وحمايتها.'],
    ['الأطفال والحسابات','لا يطلب رتّل اسمًا أو بريدًا إلكترونيًا أو حسابًا أو بيانات دفع. ولا يجمع رتّل المعلومات الشخصية عن قصد.'],
    ['التعديلات والتواصل','قد نحدّث هذه السياسة عند تغيير التطبيق أو الموقع، وستُنشر النسخة الحالية في هذه الصفحة. للأسئلة، تواصل مع القائمين على المشروع عبر مستودع GitHub العام: <a href="https://github.com/zarsalene/Quran_AI_app/issues">رتّل على GitHub</a>.']
  ]}
};

const select=document.querySelector('#language');
const language=()=>localStorage.getItem('rattil-site-language')||navigator.language?.toLowerCase().split('-')[0]||'en';
function render(lang){const t=policy[lang]||policy.en;document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';select.value=lang;document.title=`${t.title} — Rattil`;document.querySelectorAll('[data-p]').forEach(el=>{el.textContent=t[el.dataset.p]});document.querySelector('#policy-content').innerHTML=t.sections.map(([heading,body])=>`<section><h2>${heading}</h2><p>${body}</p></section>`).join('')}
select.addEventListener('change',()=>{localStorage.setItem('rattil-site-language',select.value);render(select.value)});
document.querySelector('#year').textContent=new Date().getFullYear();
render(language());
